Input.padStick:
padStick(ix, iy, out, dz = 0.12, outer = 0.96, expo = 1) {
    out.x = 0; out.y = 0; out.mag = 0;
    if (this._padTakeoverAxes) return out;
    if (!this.pad) return out;
    const x = this.pad.axes[ix] || 0, y = this.pad.axes[iy] || 0;
    const m = Math.hypot(x, y);
    if (m <= dz) return out;
    const k = Math.min(1, (m - dz) / (outer - dz));
    const c = expo === 1 ? k : Math.pow(k, expo);
    out.x = (x / m) * c; out.y = (y / m) * c; out.mag = c;
    return out;
  }

Menus._spatial:
_spatial(from, dir) {
    const cands = this._candidates();
    if (!cands.length) return null;
    if (!from || !cands.includes(from)) return cands[0];
    const fr = from.getBoundingClientRect();
    const fcx = fr.left + fr.width / 2, fcy = fr.top + fr.height / 2;
    let best = null, bestScore = Infinity;
    for (const c of cands) {
      if (c === from) continue;
      const r = c.getBoundingClientRect();
      const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
      let primary, ortho;
      if (dir === 'down' || dir === 'up') {
        primary = dir === 'down' ? cy - fcy : fcy - cy;
        if (primary < Math.min(fr.height, r.height) * 0.3) continue;
        ortho = Math.max(0, Math.max(fr.left, r.left) - Math.min(fr.right, r.right));
      } else {
        primary = dir === 'right' ? cx - fcx : fcx - cx;
        if (primary < Math.min(fr.width, r.width) * 0.3) continue;
        ortho = Math.max(0, Math.max(fr.top, r.top) - Math.min(fr.bottom, r.bottom));
      }
      const score = primary + ortho * 3 + Math.abs(dir === 'down' || dir === 'up' ? cx - fcx : cy - fcy) * 0.15;
      if (score < bestScore) { bestScore = score; best = c; }
    }
    if (!best && this._scr && this._scr.wrap && (dir === 'down' || dir === 'up')) {
      let ext = null, ev = dir === 'down' ? Infinity : -Infinity;
      for (const c of cands) {
        const r = c.getBoundingClientRect();
        const overl = Math.min(fr.right, r.right) - Math.max(fr.left, r.left);
        if (overl <= 0) continue;
        const cy = r.top + r.height / 2;
        if (dir === 'down' ? cy < ev : cy > ev) { ev = cy; ext = c; }
      }
      if (ext && ext !== from) best = ext;
    }
    return best;
  }

HUD._updMarkers:
_updMarkers(ms) {
    const L = this._L;
    ms = ms || [];
    let byName = null;
    for (let i = 0; i < this.markers.length; i++) {
      const el = this.markers[i], m = ms[i];
      const k = `mk${i}`;
      if (!m) { if (L[k] !== 'x') { L[k] = 'x'; el.style.display = 'none'; } continue; }
      const on = !!m.onScreen;
      let ac;
      if (typeof m.specialReady !== 'boolean' || !m.weapon) {
        if (!byName) {
          const actors = this._actors();
          if (!this.lab) this._actorRefsMatch = G.match;
          byName = this._byName;
          if (!byName || this._byNameN !== actors.length || this._byNameA !== actors[0]) {
            byName = this._byName = new Map(actors.map((a) => [a.name, a]));
            this._byNameN = actors.length; this._byNameA = actors[0];
          }
        }
        ac = byName.get(m.name);
      }
      const ready = typeof m.specialReady === 'boolean' ? m.specialReady : !!(ac && ac.specialReady && ac.specialReady());
      const w = m.weapon || (ac && ac.weaponId);
      const far = m.dist != null ? clamp((m.dist - 14) / 20, 0, 1) : 0;
      const key = `${(+m.x).toFixed(0)}|${(+m.y).toFixed(0)}|${on ? 1 : 0}|${on ? 0 : (+m.angle || 0).toFixed(2)}|${m.name}|${m.color}|${ready ? 1 : 0}|${far.toFixed(1)}|${w || ''}`;
      if (L[k] === key) continue;
      const prev = L[k];
      L[k] = key;
      if (prev === 'x' || !prev) el.style.display = '';
      if (el._name !== m.name || el._weapon !== w) {
        el._name = m.name; el._weapon = w;
        el.querySelector('.iw-mk__tag b').textContent = m.name || '';
        el.querySelector('.iw-mk__w').innerHTML = w ? weaponIcon(kindOf(w)) : '';
      }
      const col = toHex(m.color, '#ffffff');
      if (el._col !== col) { el._col = col; colorVars(el, 'c', col); }
      if (el._on !== on) { el._on = on; el.classList.toggle('is-off', !on); }
      if (el._ready !== ready) { el._ready = ready; el.classList.toggle('is-ready', ready); }
      el.style.setProperty('--far', far.toFixed(2));
      el.style.transform = `translate3d(${(+m.x).toFixed(1)}px,${(+m.y).toFixed(1)}px,0)`;
      if (!on) el.lastChild.style.transform = `rotate(${(+m.angle || 0).toFixed(3)}rad)`;
    }
  }

FX.superJumpCharge:
superJumpCharge(pos, color, k = 0.5) {
    const col = this._color(color, this._col);
    const q = Math.max(0.5, this.q);
    // rising spiral of sparkles + droplets
    let n = Math.floor((24 + 30 * k) * this._dt * q + rand());
    this._colB.copy(col).lerp(_white, 0.5).multiplyScalar(2.2);
    while (n-- > 0) {
      const a = this._time * 9 + rand() * TAU, r = 0.75 - 0.35 * k + rand() * 0.15;
      const c = Math.cos(a), s = Math.sin(a);
      this._sprite(this.glows, pos.x + c * r, pos.y + 0.1 + rand() * 0.4, pos.z + s * r, -s * 2.4, 2.5 + 2 * k, c * 2.4, this._colB, 0.12, 0.05, 0.4, 1, 1.5, 0, G_STAR + 1, 0.03, 1.5);
    }
    n = Math.floor((14 + 24 * k) * this._dt * q + rand());
    while (n-- > 0) {
      const a = rand() * TAU, r = 0.5 + rand() * 0.3;
      this._spawnDrop(pos.x + Math.cos(a) * r, pos.y + 0.05, pos.z + Math.sin(a) * r, -Math.sin(a) * 1.8, 2.5 + rand() * 3 * (0.5 + k), Math.cos(a) * 1.8, col, 0.025 + rand() * 0.025, 0.7, 0.8, 1.3, F_QUIET);
    }
    this._colB.copy(col).lerp(_white, 0.2).multiplyScalar(1.4 + 2 * k);
    this._sprite(this.glows, pos.x, pos.y + 0.45, pos.z, 0, 0, 0, this._colB, 0.7 + 0.5 * k, 0.7 + 0.5 * k, Math.max(0.03, this._dt * 1.6), 0.7, 0, 0, G_SOFT + 2 * k, 0, 0);
    if (rand() < 5 * this._dt) this._ringRaw(_v2.set(pos.x, pos.y + 0.02, pos.z), UP, col, 1.1 + 0.4 * k, 0.35, R_THIN, 0.7, 1);
  }

function.noiseBuffer:
function noiseBuffer(ctx, kind = 'white') {
  const c = cache(ctx);
  const key = 'noise:' + kind;
  let b = c.get(key);
  if (b) return b;
  const sr = ctx.sampleRate, len = Math.floor(sr * 2);
  b = ctx.createBuffer(1, len, sr);
  const d = b.getChannelData(0);
  const rnd = mulberry32(kind === 'white' ? 11 : kind === 'pink' ? 23 : 37);
  const w = kind === 'white' ? d : new Float32Array(len);
  for (let i = 0; i < len; i++) w[i] = rnd() * 2 - 1;
  if (kind === 'white') { /* The channel already owns the exact Float32 samples. */ }
  else {
    // every IIR runs twice around the loop (warm-up pass, then the written pass) so its state at the end equals
    // its state at the start → the colored noise is exactly periodic and loops without a step
    let b0 = 0, b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0, b6 = 0, last = 0;
    for (let pass = 0; pass < 2; pass++) {
      for (let i = 0; i < len; i++) {
        const x = w[i];
        let y;
        if (kind === 'pink') {
          b0 = 0.99886 * b0 + x * 0.0555179; b1 = 0.99332 * b1 + x * 0.0750759; b2 = 0.969 * b2 + x * 0.153852;
          b3 = 0.8665 * b3 + x * 0.3104856; b4 = 0.55 * b4 + x * 0.5329522; b5 = -0.7616 * b5 - x * 0.016898;
          y = b0 + b1 + b2 + b3 + b4 + b5 + b6 + x * 0.5362; b6 = x * 0.115926;
        } else { last = (last + 0.02 * x) / 1.02; y = last; }
        if (pass) d[i] = y;
      }
    }
    // DC-block (one-pole HPF ~25 Hz), also circular
    const a = Math.exp((-2 * Math.PI * 25) / sr);
    let y = 0, px = d[len - 1];
    const tmp = w;
    for (let pass = 0; pass < 2; pass++) {
      for (let i = 0; i < len; i++) { const x = d[i]; y = a * (y + x - px); px = x; if (pass) tmp[i] = y; }
    }
    d.set(tmp);
  }
  let mean = 0;
  for (let i = 0; i < len; i++) mean += d[i];
  mean /= len;
  for (let i = 0; i < len; i++) d[i] -= mean;
  let ss = 0;
  for (let i = 0; i < len; i++) ss += d[i] * d[i];
  const g = 0.3 / Math.sqrt(ss / len);
  for (let i = 0; i < len; i++) d[i] *= g;
  c.set(key, b);
  return b;
}

MobileInput._layoutAll:
_layoutAll() {
    if (!this.root) return;
    this._safeBox = this._safe();
    this._H = layoutUnit();
    for (const id of ORDER) {
      const el = this.els[id]; if (!el) continue;
      const b = this._box(id);
      (this._hitBoxes || (this._hitBoxes = Object.create(null)))[id] = b;
      const diameter = `${b.d.toFixed(1)}px`, left = (b.x - b.d / 2).toFixed(1) + 'px', top = (b.y - b.d / 2).toFixed(1) + 'px';
      const transform = id === 'stick' ? `translate3d(${left},${top},0)` : 'none';
      const key = diameter + '|' + left + '|' + top + '|' + transform;
      if (el._queueGeometry !== key) {
        el.style.width = el.style.height = diameter;
        if (id === 'stick') el.style.transform = transform;
        else { el.style.left = left; el.style.top = top; el.style.transform = transform; }
        el._queueGeometry = key;
      }
      if (id === 'stick') { this._stickHome = b; this._stickR = b.d / 2; }
    }
    if (!this._stick.active) this._drawStick(false);
  }

InkFX.update:
update(dt, decks) {
    if (this._iwFxIdle) return;
    const P = this.P, V = this.V;
    let top = -1;
    for (let i = 0; i < this.N; i++) {
      const k = this.K[i];
      if (!k) continue;
      const i3 = i * 3;
      const age = (this.A[i] += dt);
      let x = P[i3], y = P[i3 + 1], z = P[i3 + 2];
      const r = this.R[i];
      if (k === 3) {
        // bubble: rises with a lazy wobble, swells and pops
        const L = this.L[i];
        if (age >= L) { this.K[i] = 0; this.mesh.setMatrixAt(i, ZERO_M); continue; }
        const S = this.S[i];
        y += V[i3 + 1] * dt * (0.75 + 0.25 * Math.sin(age * 1.9 + S));
        x = V[i3] + 0.035 * Math.sin(age * 1.7 + S) * Math.min(1, age);
        z = V[i3 + 2] + 0.035 * Math.cos(age * 1.3 + S * 1.3) * Math.min(1, age);
        const grow = eOut3(age / 0.5), pop = age > L - 0.14 ? 1 + 0.35 * ((age - (L - 0.14)) / 0.14) : 1;
        const vis = age > L - 0.03 ? 0 : 1;
        const wob = 1 + 0.12 * Math.sin(age * 8 + S);
        const sc = r * grow * pop * vis;
        _q.identity();
        _s.set(sc / Math.sqrt(wob), sc * wob, sc / Math.sqrt(wob));
      } else {
        const g = k === 2 ? 9.5 : k === 4 ? 9.8 : 10.5;
        V[i3 + 1] -= g * dt;
        if (k === 4 && V[i3 + 1] < -5.2) V[i3 + 1] = -5.2;
        const py = y;
        x += V[i3] * dt; y += V[i3 + 1] * dt; z += V[i3 + 2] * dt;
        let landed = false;
        for (let d = 0; d < decks.length; d++) {
          const D = decks[d];
          if (py >= D.y && y < D.y) {
            const dx = x - D.x, dz = (z - D.z) / (D.zs || 1);   // zs: oval decks (lobby stage)
            if (dx * dx + dz * dz < D.r * D.r) { landed = true; this.K[i] = 0; this.mesh.setMatrixAt(i, ZERO_M); this._land(i, k, x, D.y, z); break; }
          }
        }
        if (landed) continue;
        if (y < -3.5 || age > this.L[i]) { this.K[i] = 0; this.mesh.setMatrixAt(i, ZERO_M); continue; }
        const vx = V[i3], vy = V[i3 + 1], vz = V[i3 + 2], sp = Math.hypot(vx, vy, vz);
        const st = 1 + Math.min(sp * 0.055, 0.9);
        if (sp > 0.05) _q.setFromUnitVectors(UPV, _d.set(vx / sp, vy / sp, vz / sp)); else _q.identity();
        const grow = k === 2 ? eOut3(age / 0.12) : 1;
        _s.set((r * grow) / Math.sqrt(st), r * grow * st, (r * grow) / Math.sqrt(st));
      }
      P[i3] = x; P[i3 + 1] = y; P[i3 + 2] = z;
      _m4.compose(_v.set(x, y, z), _q, _s);
      this.mesh.setMatrixAt(i, _m4);
      top = i;
    }
    this.mesh.count = top + 1;
    if (this.mesh.count > 0) this.mesh.instanceMatrix.needsUpdate = true;
    // splats: pop in with overshoot, sink back into the surface
    let sTop = -1;
    for (let j = 0; j < this.SN; j++) {
      const L = this.SL[j];
      if (this.SA[j] >= L) continue;
      const a = (this.SA[j] += dt);
      if (a >= L) { this.splats.setMatrixAt(j, ZERO_M); continue; }
      const grow = backOut(a / 0.16, 2.2), shrink = 1 - eInOut((a - L * 0.5) / (L * 0.5));
      const s = this.SS[j] * grow * Math.max(0.001, shrink);
      _q.setFromAxisAngle(UPV, this.SY[j]);
      _s.set(s, s * (0.35 + 0.65 * shrink), s);
      _m4.compose(_v.set(this.SP[j * 3], this.SP[j * 3 + 1], this.SP[j * 3 + 2]), _q, _s);
      this.splats.setMatrixAt(j, _m4);
      sTop = j;
    }
    // ripple rings: expand and flatten out
    let rTop = -1;
    for (let j = 0; j < this.RN; j++) {
      const L = this.RL[j];
      if (this.RA[j] >= L) continue;
      const a = (this.RA[j] += dt);
      if (a >= L) { this.rings.setMatrixAt(j, ZERO_M); continue; }
      const f = a / L, rad = lerp(this.R0[j], this.R1[j], eOut3(f)), h = (1 - f) * (1 - f);
      _q.identity();
      _s.set(rad, Math.max(0.001, rad * 0.55 * h), rad);
      _m4.compose(_v.set(this.RP[j * 3], this.RP[j * 3 + 1], this.RP[j * 3 + 2]), _q, _s);
      this.rings.setMatrixAt(j, _m4);
      rTop = j;
    }
    // keep counts covering every live slot (dead slots in between hold zero matrices)
    this.splats.count = this._span(this.SA, this.SL, this.SN, sTop);
    this.rings.count = this._span(this.RA, this.RL, this.RN, rTop);
    if (this.splats.count > 0) this.splats.instanceMatrix.needsUpdate = true;
    if (this.rings.count > 0) this.rings.instanceMatrix.needsUpdate = true;
    if (!this.mesh.count && !this.splats.count && !this.rings.count) {
      this._iwFxIdle = true;
      for (let i = 0; i < this.N; i++) if (this.K[i]) { this._iwFxIdle = false; break; }
    }
  }

Sparkles.update:
update(dt) {
    if (this._iwFxIdle) return;
    let top = -1;
    for (let i = 0; i < this.N; i++) {
      if (this.A[i] >= this.L[i]) continue;
      const a = (this.A[i] += dt), L = this.L[i];
      if (a >= L) { this.mesh.setMatrixAt(i, ZERO_M); continue; }
      const f = a / L, env = Math.pow(Math.sin(Math.PI * f), 1.6) * (0.82 + 0.18 * Math.sin(a * 31 + i));
      const s = this.S[i] * env;
      _m4.makeScale(s, s, s).setPosition(this.P[i * 3], this.P[i * 3 + 1] + a * 0.05, this.P[i * 3 + 2]);
      this.mesh.setMatrixAt(i, _m4);
      top = i;
    }
    let n = top + 1;
    for (let i = this.N - 1; i >= n; i--) if (this.A[i] < this.L[i]) { n = i + 1; break; }
    this.mesh.count = n;
    if (this.mesh.count > 0) this.mesh.instanceMatrix.needsUpdate = true;
    this._iwFxIdle = this.mesh.count === 0;
  }

